Send SMS.code:
// Send an SMS.
sendSMS({
  // Registered sender ID.
  from: 'MOH-Ghana',
  // Recipient in international format.
  to: $.data.phone, // e.g. '233241234567'
  content: 'Reminder: your child is due for the measles vaccine this week.',
});

Send Appointment Reminder.code:
// Send a personalised appointment reminder.
sendSMS({
  from: 'ClinicSMS',
  to: $.data.patient.phone,
  content: `Hello ${$.data.patient.firstName}, your appointment at ${$.data.facility} is on ${$.data.appointmentDate}.`,
});

Send Payment Confirmation.code:
// Confirm a cash transfer to a beneficiary.
sendSMS({
  from: 'LEAP',
  to: $.data.beneficiaryPhone,
  content: `GHS ${$.data.amount} has been sent to your mobile money wallet. Ref: ${$.data.reference}`,
});

Get Message Status.code:
// Check whether a message was delivered.
request(
  // 1) HTTP method.
  'GET',
  // 2) Message id returned by sendSMS (MessageId).
  `/messages/${$.data.MessageId}`
);
